tfix) with ESMTP id C 6534470C; Wed, 24 Jul 2002 11:34:57+0200 (CEST) X-Mailer: exmh version 2.5_20020724 01/15/2001 with nmh-1.0.4 To: Chris Garrigues <cwg-dated-1027805573.3ce2ae@DeepEddy.Com>, exmh-workers@redhat.com Subject: PATCH (was: Re: Another bug) In-Reply-To: Message from Anders Eriksson <aeriksson@fastmail.fm> of Tue, 23 Jul 2002 02:20:35+0200. <20020723002041.2624D470D@tippex.localdomain> MIME-Version: 1.0 Content-Type: multipart/mixed ; boundary==_Exmh_6514812010 From: Anders Eriksson <aeriksson@fastmail.fm> Message-Id: <20020724093457.D1035470D@tippex.localdomain> X-Loop: exmh-workers@spamassassin.taint.org Sender: exmh-workers-admin@spamassassin.taint.org Errors-To: exmh-workers-admin@spamassassin.taint.org X-Beenthere: exmh-workers@spamassassin.taint.org X-Mailman-Version: 2.0.1 Precedence: bulk List-Help: <mailto:exmh-workers-request@spamassassin.taint.org?subject=help> List-Post: <mailto:exmh-workers@spamassassin.taint.org> List-Subscribe: < https://listman.spamassassin.taint.org/mailman/listinfo/exmh-workers>, <mailto:exmh-workers-request@redhat.com?subject=subscribe> List-Id: Discussion list for EXMH developers <exmh-workers.spamassassin.taint.org> List-Unsubscribe: < https://listman.spamassassin.taint.org/mailman/listinfo/exmh-workers>, <mailto:exmh-workers-request@redhat.com?subject=unsubscribe> List-Archive: < https://listman.spamassassin.taint.org/mailman/private/exmh-workers/> Date: Wed, 24 Jul 2002 11:34:52+0200 This is a multipart MIME message. -=_Exmh_6514812010 Content-Type: text/plain; charset=us-ascii cwg-dated-1027805573.3ce2ae@DeepEddy.Com said: > I just checked in a code cleanup which does not address this issue, > but does take a machete to code right around it . You ought to'cvs > update'and see if your issue becomes any clearer with all the > brush removed. > My patch notes that'msgid'and'line'are redundant with one > another and removes one or the other from functions which takes > both . The callers are then changed to pass what the function > expects . In the case of Msg_Change, the'line'argument is removed > and we only have the msgid argument.Ftoc_ClearCurrent is now the > first line of MsgChange . The following patch removes Ftoc_RescanLine in favour of a Ftoc_RescanLines.It runs scan(1) on a list of lines and updates ftoc accordingly . The patch also changes all the callers to make use of it . It also changes Ftoc_ClearCurrent to work of an argument instead of falsily clearing a message that is still Current on disk . All in an effort to get a one-to-one disk-display correspondence . It does add ~30 - ~ 75 ms (~<10%) to the execution time depending on folder size due to the invocation of scan . However this version does not try to second guess the mh version of scan so if you have exotic scanlines it tells the truth . As a side effect the + sign now corresponds better to what is on disk . Comments appreciated.I am going to be offlike for a couple of days, so I send the cvs different rather than putting it in the cvs. /Anders -=_Exmh_6514812010 Content-Type: application/x-patch ; name=exmh.patch Content-Description: exmh . patch Content-Disposition: attachment; filename=exmh.patch Index: lib/ftoc.tcl = RCS file: /cvsroot/exmh/exmh/lib/ftoc.tcl,v retrieving revision 1.29 different-you-b-B-w-p-r1.29 ftoc . tcl - lib/ftoc.tcl22 Jul 2002 21:46:35-00001.29 + lib/ftoc.tcl24 Jul 2002 09:16:25-0000 @ -558,7+558,7 @ proc FtocPickRange { {addcurrent 0} } { if {$addcurrent} { Ftoc_RangeHighlight $ftoc(curLine) $ftoc(curLine) } -Ftoc_ClearCurrent+Ftoc_ClearCurrent $ftoc(curLine) Msg_ClearCurrent set ftoc(curLine) {} } @ -611,31+611,55 @ proc Ftoc_NewFtoc {} { # Ftoc_ClearCurrent and Ftoc_Change are two parts of # dinking the ftoc display when advancing a message. -proc Ftoc_ClearCurrent {} { - # Clear display of current message +# +# Make line no longer appear as the currently selected line +# + +proc Ftoc_ClearCurrent { line } { global ftoc exwin set ftoc(pickone) 1 set ftoc(lineset) {} - if {$ftoc(curLine) = {}} { -set ftoc(curLine) [Mh_Cur $ftoc(folder)] - } - if {$ftoc(curLine) != {}} { -$exwin(ftext) tag remove cur $ftoc(curLine).0 $ftoc(curLine).end-Ftoc_RescanLine $ftoc(curLine) - } - return $ftoc(curLine) -} -proc Ftoc_Change { line {show show} } { +#We do not need this any more since we work off the line +#argument, not $ftoc(curLine) +# if {$ftoc(curLine) = {}} { +# set ftoc(curLine) [Mh_Cur $ftoc(folder)] +# } +# if {$ftoc(curLine) != {}} { +# $exwin(ftext) tag remove cur $ftoc(curLine).0 $ftoc(curLine).end +# Ftoc_RescanLine $ftoc(curLine) +# } + #should check that 0<$line<last line and error otherwise + $exwin(ftext) tag remove cur $line.0 $line.end+Ftoc_RescanLines [list $line] + +# return $ftoc(curLine) +} + +# +# Make newline the currently selected line +# optionally clear oldline from such attribution +# +proc Ftoc_Change { newline {oldline {}}} { + global ftoc exwin-set ftoc(curLine) $line + + if {![info exists oldline] || ($oldline=$newline)} { + set oldline {} + } + set ftoc(curLine) $newline if {$ftoc(curLine) = {}} { set ok 0 } else { -if {$show = show} { $exwin(ftext) tag remove unseen $ftoc(curLine).0 $ftoc(curLine).end+if {$oldline != {}} { + set ftoc(pickone) 1+set ftoc(lineset) {} + $exwin(ftext) tag remove cur $oldline.0 $oldline.end+Ftoc_RescanLines [list $ftoc(curLine) $oldline] +} else { + Ftoc_RescanLines [list $ftoc(curLine)] } -Ftoc_RescanLine $ftoc(curLine) + $exwin(ftext) tag add cur $ftoc(curLine).0 $ftoc(curLine).end set top [$exwin(ftext) index . 0,4] if [catch {expr {$top+1}}] {set top 0};# trap 100.-1 format, iconic @ -695,7+720,10 @ proc Ftoc_MarkSeen { ids } { } } } -proc Ftoc_RescanLine { ix {plus none} } { +# +# This one is not used any more . Kept here for reference +# +proc Ftoc_RescanLine_old { ix {plus none} } { global exmh exwin ftoc if [catch { set text [$exwin(ftext) get ${ix}.0 ${ix}.end] @ -737,6+765,57 @ proc Ftoc_RescanLine { ix {plus none} } Exmh_Error FtocRescanLine $ix : $message } } + + +# +# Rescans a set of lines and updates the ftoc as needed +# lines_in: list of line numbers . Ranges (e.g.200-210) are not allowed +# +proc Ftoc_RescanLines { lines_in } { + global exmh exwin ftoc mhProfile + + Exmh_Debug Ftoc_RescanLines [ time { + #Sort the lines and weed out duplicates. + #They creep in when we change folders + #set lastCandidate {} + #foreach newCandidate [lsort-integer $lines_in] { + # if {$newCandidate != $lastCandidate} { + # lappend lines $newCandidate + # Exmh_Debug * $lines + # set lastCandidate $newCandidate + # } + #} + #Never mind dupechecking . The only potential is checked for in + #Ftoc_Change and the above takes time (~8 ms) + set lines [lsort-integer $lines_in] + + foreach line $lines { + lappend msgnos [Ftoc_MsgNumber $line] + } + set input [open |$mhProfile(scan-proc) \ + [list +$ftoc(folder)] \ + [join $msgnos] \ + -width $ftoc(scanWidth)] + set texts [split [string trim [read $input] 
 ] 
 ] + catch {close $input} + #Exmh_Debug * lines=$lines
msgnos=$msgnos
texts=$texts + + set ll [llength $lines] + for {set i 0} {$i<$ll} {incr i} { + set line [lindex $lines $i] + set tags [$exwin(ftext) tag names $line.0] + $exwin(ftext) configure-state normal + $exwin(ftext) delete $line.0 $line.end + $exwin(ftext) insert $line.0 [lindex $texts $i] + $exwin(ftext) configure-state disabled+foreach tag $tags { + $exwin(ftext) tag add $tag $line.0 $line.end + } + } + } + ] +} + proc Ftoc_NextImplied { {show show} {implied implied} } { global ftoc if {$ftoc(implied) && $ftoc(direction) = prev} { @ -793,7+872,7 @ proc Ftoc_NextFolder { {implied no} } { # If on last message, clear display because the # message is moved or deleted if {$ftoc(curLine) != {}} { -Ftoc_ClearCurrent+Ftoc_ClearCurrent $ftoc(curLine) Msg_ClearCurrent } Exmh_Status " @ -809,7+888,7 @ proc Ftoc_NextFolder { {implied no} } { return } else { set ftoc(softChange) 1-Ftoc_ClearCurrent+Ftoc_ClearCurrent $ftoc(curLine) Msg_ClearCurrent Exmh_Status Exmh_Status End of folder; <Next> => $f warn @ -1113,7+1192,7 @ proc FtocCommit {tagname commitProc {cop set ftoc(displayDirty) 1 Ftoc_ClearMsgCache if {$msgid = $curid} { -Ftoc_ClearCurrent+Ftoc_ClearCurrent $ftoc(curLine) Msg_ClearCurrent } if {$L = $ftoc(curLine)} { Index: lib/message.tcl = RCS file: /cvsroot/exmh/exmh/lib/message.tcl,v retrieving revision 1.21 different-you-b-B-w-p-r1.21 message . tcl - lib/message.tcl22 Jul 2002 21:23:48-00001.21 + lib/message.tcl24 Jul 2002 09:16:26-0000 @ -73,10+73,20 @ proc Msg_ShowUnseen { {show show} } { return 0 } proc Msg_ClearCurrent { } { - global message exmh+global message exmh ftoc + # Are there cases where this is not true? + if {$ftoc(folder) = $exmh(folder)} { + set prevline [Ftoc_FindMsg [Mh_Cur $ftoc(folder)]] + if {$prevline = {}} { + unset prevline + } + } set message(id) {};# Clear current message set message(dpy) {};# and currently displayed message Mh_ClearCur $exmh(folder) + if {[info exists prevline]} { + Ftoc_ClearCurrent $prevline + } MsgClear Buttons_Current 0 Uri_ClearCurrent @ -117,13+127,13 @ proc Msg_Change {msgid {show show} } { Exmh_Debug Msg_Change [time [list MsgChange $msgid $show]] } proc MsgChange {msgid {show show}} { - global exmh exwin message mhProfile+global exmh exwin message mhProfile ftoc-Ftoc_ClearCurrent+set prevline [Ftoc_FindMsg [Mh_Cur $ftoc(folder)]] Mh_SetCur $exmh(folder) $msgid Ftoc_ShowSequences $exmh(folder) set line [Ftoc_FindMsg $msgid] - if {! [Ftoc_Change $line $show]} { + if {! [Ftoc_Change $line $prevline]} { Exmh_Status Cannot find message $msgid-Rescan? } else { if {$message(id) = {}} { @ -652,14+662,17 @ proc Msg_UUdecode {} { } proc Msg_MarkUnseen {} { - global exmh+global exmh ftoc Msg_CheckPoint Ftoc_Iterate line { set msgid [Ftoc_MsgNumber $line] Mh_MarkUnseen $exmh(folder) $msgid } - Msg_ClearCurrent-Ftoc_ClearCurrent+Ftoc_RescanLines $ftoc(lineset) + #Why was this needed? + #Msg_ClearCurrent + #Not needed anymore + #Ftoc_ClearCurrent Flist_ForgetUnseen $exmh(folder) Ftoc_ShowSequences $exmh(folder) } Index: lib/scan.tcl = RCS file: /cvsroot/exmh/exmh/lib/scan.tcl,v retrieving revision 1.21 different-you-b-B-w-p-r1.21 scan . tcl - lib/scan.tcl22 Jul 2002 22:39:29-00001.21 + lib/scan.tcl24 Jul 2002 09:16:26-0000 @ -265,7+265,7 @ proc Scan_CacheUpdate {} { # this thing. # if !$ftoc(displayValid) { -set curLine [Ftoc_ClearCurrent];# Clear + +Ftoc_ClearCurrent $ftoc(curLine) ;# Clear+if [file writable $cacheFile] { set scancmd exec $mhProfile(scan-proc) [list +$folder] \ -width $ftoc(scanWidth) > [list $cacheFile] @ -273,12+273,12 @ proc Scan_CacheUpdate {} { Exmh_Status failed to rescan folder $folder: $err warn } } -Ftoc_Change $curLine;# Restore it+Ftoc_Change $ftoc(curline) ;# Restore it } elseif [catch { set cacheIO [open $cacheFile w] -set curLine [Ftoc_ClearCurrent];# Clear + +Ftoc_ClearCurrent $ftoc(curLine) ;# Clear+set display [$exwin(ftext) get 1.0 end-1 char"] -Ftoc_Change $curLine;# Restore it+Ftoc_Change $ftoc(curline) ;# Restore it puts $cacheIO $display nonewline close $cacheIO set ftoc(displayDirty) 0 -=_Exmh_6514812010- _Exmh-workers mailing list Exmh-workers@redhat.com https://listman.redhat.com/mailman/listinfo/exmh-workers

